// Generated by tooling/unicode-cases/regexp.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Context: RegExp folding has no word-final contextual sigma mapping.
const pattern0 = /^\u03a3$/i;
const pattern1 = /^\u03a3$/iu;
const pattern2 = /^\u03a3$/iv;
const samples: [string, boolean, boolean, boolean][] = [
  ["\u03a3", true, true, true],
  ["\u03c3", true, true, true],
  ["\u03c2", true, true, true],
  ["\u03c4", false, false, false],
  ["\u0391\u03a3", false, false, false],
];
for (const sample of samples) {
  assert.sameValue(pattern0.test(sample[0]), sample[1], "sigma-three-forms pattern 0");
  assert.sameValue(pattern1.test(sample[0]), sample[2], "sigma-three-forms pattern 1");
  assert.sameValue(pattern2.test(sample[0]), sample[3], "sigma-three-forms pattern 2");
}
